CREATE OR REPLACE FUNCTION public.is_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN ('librarian','admin','super_admin')); $$;
CREATE OR REPLACE FUNCTION public.is_admin(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN ('admin','super_admin')); $$;
CREATE TABLE public.admin_audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, action text NOT NULL, entity text NOT NULL, entity_id text, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_audit_log TO authenticated;
GRANT ALL ON public.admin_audit_log TO service_role;
ALTER TABLE public.admin_audit_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY "super admin audit read" ON public.admin_audit_log FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'super_admin'));
CREATE OR REPLACE FUNCTION public.audit_management_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL THEN INSERT INTO public.admin_audit_log(actor_id,action,entity,entity_id) VALUES(auth.uid(),TG_OP,TG_TABLE_NAME,COALESCE(to_jsonb(NEW)->>'id',to_jsonb(OLD)->>'id',to_jsonb(NEW)->>'user_id',to_jsonb(OLD)->>'user_id')); END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END; $$;
CREATE TRIGGER audit_roles AFTER INSERT OR UPDATE OR DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.audit_management_change();
CREATE TRIGGER audit_books AFTER INSERT OR UPDATE OR DELETE ON public.books FOR EACH ROW EXECUTE FUNCTION public.audit_management_change();
CREATE TRIGGER audit_copies AFTER INSERT OR UPDATE OR DELETE ON public.book_copies FOR EACH ROW EXECUTE FUNCTION public.audit_management_change();
CREATE TRIGGER audit_rules AFTER UPDATE ON public.library_settings FOR EACH ROW EXECUTE FUNCTION public.audit_management_change();
CREATE TRIGGER audit_fines AFTER INSERT OR UPDATE OR DELETE ON public.fines FOR EACH ROW EXECUTE FUNCTION public.audit_management_change();
CREATE TRIGGER audit_loans AFTER INSERT OR UPDATE OR DELETE ON public.borrow_records FOR EACH ROW EXECUTE FUNCTION public.audit_management_change();
CREATE TRIGGER audit_reservations AFTER INSERT OR UPDATE OR DELETE ON public.reservations FOR EACH ROW EXECUTE FUNCTION public.audit_management_change();
DROP POLICY "staff write" ON public.books;
CREATE POLICY "admin catalogue write" ON public.books FOR ALL TO authenticated USING(public.is_admin(auth.uid())) WITH CHECK(public.is_admin(auth.uid()));
DROP POLICY "staff write" ON public.authors;
CREATE POLICY "admin authors write" ON public.authors FOR ALL TO authenticated USING(public.is_admin(auth.uid())) WITH CHECK(public.is_admin(auth.uid()));
DROP POLICY "staff write" ON public.categories;
CREATE POLICY "admin categories write" ON public.categories FOR ALL TO authenticated USING(public.is_admin(auth.uid())) WITH CHECK(public.is_admin(auth.uid()));
DROP POLICY "staff write" ON public.book_authors;
CREATE POLICY "admin book authors write" ON public.book_authors FOR ALL TO authenticated USING(public.is_admin(auth.uid())) WITH CHECK(public.is_admin(auth.uid()));
DROP POLICY "staff write" ON public.book_copies;
REVOKE INSERT, UPDATE, DELETE ON public.book_copies FROM authenticated;
DROP POLICY "staff borrow write" ON public.borrow_records;
REVOKE INSERT, UPDATE, DELETE ON public.borrow_records FROM authenticated;
DROP POLICY "staff res write" ON public.reservations;
REVOKE INSERT, UPDATE, DELETE ON public.reservations FROM authenticated;
DROP POLICY "staff fine write" ON public.fines;
REVOKE INSERT, UPDATE, DELETE ON public.fines FROM authenticated;
CREATE POLICY "staff loan read" ON public.borrow_records FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));
CREATE POLICY "staff reservation read" ON public.reservations FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));
CREATE POLICY "staff fines read" ON public.fines FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));
DROP POLICY "settings admin update" ON public.library_settings;
REVOKE UPDATE ON public.library_settings FROM authenticated;
CREATE POLICY "super admin roles read" ON public.user_roles FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'super_admin'));
CREATE OR REPLACE FUNCTION public.management_access() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.is_staff(auth.uid()) THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF; RETURN jsonb_build_object('staff',true,'admin',public.is_admin(auth.uid()),'superAdmin',public.has_role(auth.uid(),'super_admin')); END; $$;
CREATE OR REPLACE FUNCTION public.management_members() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF; RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object('id',p.id,'name',p.full_name,'email',p.email,'department',p.department,'roles',(SELECT COALESCE(jsonb_agg(r.role),'[]'::jsonb) FROM public.user_roles r WHERE r.user_id=p.id)) ORDER BY p.created_at DESC) FROM public.profiles p),'[]'::jsonb); END; $$;
CREATE OR REPLACE FUNCTION public.super_admin_set_role(_user_id uuid,_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(420197); IF NOT public.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'Super admin access required' USING ERRCODE='42501'; END IF; IF _role IS NULL THEN RAISE EXCEPTION 'Choose a role'; END IF; IF auth.uid()=_user_id THEN RAISE EXCEPTION 'You cannot change your own role'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_user_id) THEN RAISE EXCEPTION 'Member not found'; END IF; IF public.has_role(_user_id,'super_admin') AND _role<>'super_admin' AND (SELECT count(DISTINCT user_id) FROM public.user_roles WHERE role='super_admin')<=1 THEN RAISE EXCEPTION 'The last super admin cannot be removed'; END IF; DELETE FROM public.user_roles WHERE user_id=_user_id; INSERT INTO public.user_roles(user_id,role) VALUES(_user_id,_role); END; $$;
CREATE OR REPLACE FUNCTION public.management_save_book(_book jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; aid uuid; a text; pos integer:=0; BEGIN IF NOT public.is_admin(auth.uid()) THEN RAISE EXCEPTION 'Admin access required' USING ERRCODE='42501'; END IF; IF length(trim(COALESCE(_book->>'title','')))<1 OR length(trim(COALESCE(_book->>'isbn','')))<1 THEN RAISE EXCEPTION 'Title and ISBN are required'; END IF; IF length(_book->>'title')>300 OR length(_book->>'isbn')>40 THEN RAISE EXCEPTION 'Title or ISBN is too long'; END IF; bid:=NULLIF(_book->>'id','')::uuid; IF bid IS NULL THEN INSERT INTO public.books(title,isbn) VALUES(trim(_book->>'title'),trim(_book->>'isbn')) RETURNING id INTO bid; END IF; UPDATE public.books SET title=trim(_book->>'title'),isbn=trim(_book->>'isbn'),publisher=NULLIF(_book->>'publisher',''),department=NULLIF(_book->>'department',''),language=COALESCE(NULLIF(_book->>'language',''),'English'),publication_year=NULLIF(_book->>'publicationYear','')::integer,description=NULLIF(_book->>'description',''),category_id=NULLIF(_book->>'categoryId','')::uuid,featured=COALESCE((_book->>'featured')::boolean,false) WHERE id=bid; IF NOT FOUND THEN RAISE EXCEPTION 'Book not found'; END IF; DELETE FROM public.book_authors WHERE book_id=bid; FOR a IN SELECT jsonb_array_elements_text(COALESCE(_book->'authors','[]'::jsonb)) LOOP IF trim(a)='' THEN CONTINUE; END IF; SELECT id INTO aid FROM public.authors WHERE lower(name)=lower(trim(a)) LIMIT 1; IF aid IS NULL THEN INSERT INTO public.authors(name) VALUES(trim(a)) RETURNING id INTO aid; END IF; INSERT INTO public.book_authors(book_id,author_id,position) VALUES(bid,aid,pos) ON CONFLICT DO NOTHING; pos:=pos+1; END LOOP; RETURN bid; END; $$;
CREATE OR REPLACE FUNCTION public.management_save_copy(_book_id uuid,_barcode text,_shelf text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; BEGIN IF NOT public.is_admin(auth.uid()) THEN RAISE EXCEPTION 'Admin access required' USING ERRCODE='42501'; END IF; IF length(trim(COALESCE(_barcode,'')))=0 OR length(_barcode)>100 THEN RAISE EXCEPTION 'Enter a valid barcode'; END IF; INSERT INTO public.book_copies(book_id,barcode,shelf_location) VALUES(_book_id,trim(_barcode),NULLIF(trim(_shelf),'')) RETURNING id INTO cid; RETURN cid; END; $$;
CREATE OR REPLACE FUNCTION public.management_update_settings(_loan_days integer,_fine_per_day numeric,_max_holds integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin(auth.uid()) THEN RAISE EXCEPTION 'Admin access required' USING ERRCODE='42501'; END IF; IF _loan_days IS NULL OR _loan_days<1 OR _fine_per_day IS NULL OR _fine_per_day<0 OR _max_holds IS NULL OR _max_holds<1 THEN RAISE EXCEPTION 'Loan days and maximum holds must be positive; fine rate cannot be negative'; END IF; UPDATE public.library_settings SET loan_days=_loan_days,fine_per_day=_fine_per_day,max_active_reservations=_max_holds WHERE id=1; END; $$;
REVOKE ALL ON FUNCTION public.management_access(),public.management_members(),public.super_admin_set_role(uuid,public.app_role),public.management_save_book(jsonb),public.management_save_copy(uuid,text,text),public.management_update_settings(integer,numeric,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.management_access(),public.management_members(),public.super_admin_set_role(uuid,public.app_role),public.management_save_book(jsonb),public.management_save_copy(uuid,text,text),public.management_update_settings(integer,numeric,integer) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.audit_management_change() FROM PUBLIC,anon,authenticated;